SOURCE='"""Read-only post-deploy bounded-directory acceptance. No fixture writes/commands.\nCredentials come only from the verified live Gin process and stay in memory.\nRun explicitly on the target server with --execute-loopback-readonly.\n"""\nimport argparse,hashlib,hmac,json,os,pathlib,subprocess,time,urllib.error,urllib.request\n\nORIGIN=\'http://127.0.0.1:9999\'\nBINARY=\'/home/thingspanel/thingspanel-backend-community/thingspanel-backend-community\'\nPM2=\'/root/.local/share/pnpm/pm2\'\nSTAGE=pathlib.Path(\'/opt/tp-community-actions/q09-gin-directory-efb-ci43365065896\')\nCANDIDATE=\'efb3f95f45310206fa484efb59402eb4bf7aa62f\'\nCONTRACT_SHA=\'4adb685623ed8f8fcd8ed38be4f6a95817a8dc7aa2aa2d040122f0ced964ee5a\'\nBINARY_SHA=\'564d846dcfa2138c15b6536a40abc54d8e94956408dde60b9ea8bbd9dfc748a6\'\nENCORE_ID=\'607a26929ccd73dce17c585cce17e13803dd9745692c5630e00f083dc37659a3\'\nENCORE_IMAGE=\'sha256:d284d82d112a0f12c1038aa4dfb7fd2427b38a4c0a49bb6c51078242733e9154\'\nTENANTS={\'A\':\'63a4b529\',\'B\':\'ab4fa6e9\'}\nDEVICES={\'A\':[\'c13ad287-76b1-38cd-b16e-946b37e8c88e\',\'a405851e-67ea-5932-9d79-a9eda3a0ff25\'],\'B\':[\'5dfabeeb-4115-1781-5fb7-066c951a8a91\',\'060852d7-16a6-b079-8d7d-8afd85d77969\']}\nUNKNOWN=\'00000000-0000-4000-8000-000000000000\'\nROW_FIELDS={\'id\',\'tenant_id\',\'name\',\'label\',\'device_config_id\',\'device_type\',\'is_online\'}\n\nclass CheckFailed(Exception):pass\n\ndef ensure(value,name):\n if not value:raise CheckFailed(name)\n\ndef run_json(args):\n r=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=10)\n ensure(r.returncode==0,\'runtime-inspection-failed\')\n return json.loads(r.stdout)\n\ndef process_contract(p):\n e=p[\'pm2_env\'];env=dict(e.get(\'env\') or {})\n env.update({k:v for k,v in e.items() if k.upper()==k and isinstance(v,(str,int,float))})\n fixed={k:e.get(k) for k in (\'pm_exec_path\',\'pm_cwd\',\'exec_interpreter\',\'exec_mode\',\'args\',\'node_args\',\'autorestart\',\'restart_delay\',\'max_memory_restart\',\'min_uptime\',\'max_restarts\',\'kill_timeout\',\'wait_ready\',\'listen_timeout\',\'merge_logs\',\'log_date_format\',\'uid\',\'gid\')}\n return hashlib.sha256(json.dumps({\'name\':p[\'name\'],\'pm_id\':p[\'pm_id\'],\'env\':env,\'fixed\':fixed},sort_keys=True,separators=(\',\',\':\')).encode()).hexdigest()\n\ndef identity():\n ensure(not STAGE.is_symlink(),\'stage-symlink\')\n applied=json.loads((STAGE/\'applied.private.json\').read_text())\n rows=[x for x in run_json([PM2,\'jlist\']) if x.get(\'name\')==\'thingspanel-backend-community\']\n ensure(len(rows)==1 and rows[0].get(\'pm_id\')==25,\'PM2-identity\')\n p=rows[0];ensure(process_contract(p)==CONTRACT_SHA,\'Gin-process-contract\');ensure(p.get(\'pid\')==applied.get(\'pid\') and p[\'pm2_env\'][\'status\']==\'online\',\'Gin-pid-or-status\')\n ensure(applied.get(\'binary_sha256\')==BINARY_SHA and applied.get(\'version\')==\'gin-cas-command-\'+CANDIDATE,\'apply-identity\')\n ensure(os.readlink(\'/proc/\'+str(p[\'pid\'])+\'/exe\')==BINARY,\'Gin-executable\')\n ensure(hashlib.sha256(pathlib.Path(BINARY).read_bytes()).hexdigest()==BINARY_SHA,\'Gin-binary-hash\')\n env=dict(v.split(\'=\',1) for v in pathlib.Path(\'/proc/\'+str(p[\'pid\'])+\'/environ\').read_text().split(\'\\0\') if \'=\' in v)\n token=env.get(\'GOTP_AUTOMATION_TOKEN\',\'\').strip();deployment=env.get(\'GOTP_AUTOMATION_DEPLOYMENT_ID\',\'\').strip()\n ensure(len(token)>=32 and deployment,\'service-identity-not-configured\')\n containers=run_json([\'docker\',\'inspect\',\'tp-community-main-47-encore-api-1\']);ensure(len(containers)==1,\'Encore-unique\')\n c=containers[0];ensure(c[\'Id\']==ENCORE_ID and c[\'Image\']==ENCORE_IMAGE and c[\'State\'][\'Running\'],\'Encore-identity\')\n other=dict(v.split(\'=\',1) for v in c[\'Config\'][\'Env\'] if \'=\' in v)\n ensure(hmac.compare_digest(token,other.get(\'TP_AUTOMATION_SERVICE_TOKEN\',\'\').strip()) and hmac.compare_digest(deployment,other.get(\'TP_SOURCE_DEPLOYMENT_ID\',\'\').strip()),\'shared-service-identity-mismatch\')\n return token,deployment,p[\'pid\']\n\nclass NoRedirect(urllib.request.HTTPRedirectHandler):\n def redirect_request(self,*args,**kwargs):return None\n\nclass Transport:\n def __init__(self):\n  self.opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect());self.deadline=time.monotonic()+80\n def __call__(self,method,path,headers,body=None):\n  ensure(path in [\'/internal/automation/devices/lookup\',\'/internal/automation/devices?page=1&page_size=2\',\'/internal/automation/devices?page=2&page_size=2\',\'/api/v1/sys_version\'],\'unapproved-read-route\')\n  ensure((method==\'POST\' and path.endswith(\'/lookup\')) or (method==\'GET\' and body is None),\'unapproved-method\')\n  left=self.deadline-time.monotonic();ensure(left>0,\'probe-budget-exhausted\')\n  req=urllib.request.Request(ORIGIN+path,data=None if body is None else json.dumps(body).encode(),headers=headers,method=method)\n  try:\n   with self.opener.open(req,timeout=min(5,left)) as r:status=r.status;raw=r.read(65537)\n  except urllib.error.HTTPError as e:status=e.code;raw=e.read(65537)\n  ensure(len(raw)<=65536,\'response-too-large\')\n  try:value=json.loads(raw)\n  except Exception:raise CheckFailed(\'response-not-json\') from None\n  ensure(time.monotonic()<=self.deadline,\'probe-budget-exhausted\')\n  return status,value\n\ndef response_rows(status,value,tenant):\n ensure(status==200 and isinstance(value,dict) and value.get(\'code\')==200,\'lookup-envelope\')\n data=value.get(\'data\');ensure(isinstance(data,dict) and isinstance(data.get(\'total\'),int),\'lookup-data\')\n rows=data.get(\'list\') or [];ensure(isinstance(rows,list),\'lookup-list\')\n ensure(all(isinstance(r,dict) and set(r)==ROW_FIELDS and r.get(\'tenant_id\')==tenant for r in rows),\'row-field-or-tenant-leak\')\n ensure(len({r[\'id\'] for r in rows})==len(rows),\'duplicate-rows\')\n return data,rows\n\ndef probe(token,deployment,transport):\n results=[]\n def record(name,fn):\n  try: detail=fn();results.append({\'name\':name,\'status\':\'PASS\',\'detail\':detail})\n  except Exception as e:results.append({\'name\':name,\'status\':\'FAIL\',\'reason\':str(e) if isinstance(e,CheckFailed) else type(e).__name__})\n def headers(tenant):return {\'Content-Type\':\'application/json\',\'Authorization\':\'Bearer \'+token,\'X-Automation-Deployment\':deployment,\'X-Automation-Tenant\':tenant}\n def lookup(label,ids,expected):\n  data,rows=response_rows(*transport(\'POST\',\'/internal/automation/devices/lookup\',headers(TENANTS[label]),{\'ids\':ids}),TENANTS[label])\n  ensure(data[\'total\']==len(expected) and {r[\'id\'] for r in rows}==set(expected),\'exact-IDs-mismatch\')\n  return {\'tenant\':TENANTS[label],\'returned_ids\':sorted(r[\'id\'] for r in rows),\'total\':data[\'total\']}\n for label,other in [(\'A\',\'B\'),(\'B\',\'A\')]:\n  record(label+\' own two fixtures\',lambda label=label:lookup(label,DEVICES[label],DEVICES[label]))\n  record(label+\' mixed own foreign unknown dedupe\',lambda label=label,other=other:lookup(label,DEVICES[label]+DEVICES[other]+[UNKNOWN,DEVICES[label][0]],DEVICES[label]))\n  record(label+\' foreign only omitted\',lambda label=label,other=other:lookup(label,DEVICES[other],[]))\n  record(label+\' unknown omitted\',lambda label=label:lookup(label,[UNKNOWN],[]))\n def reject(name,body,change,expected):\n  h=headers(TENANTS[\'A\']);h.update(change)\n  status,value=transport(\'POST\',\'/internal/automation/devices/lookup\',h,body)\n  ensure(status==expected and isinstance(value,dict) and value.get(\'code\')==expected,\'unexpected-rejection\')\n  ensure(\'data\' not in value,\'rejection-returned-data\')\n  return {\'http_status\':status,\'has_data\':False}\n for name,body,change,expected in [\n  (\'anonymous\',{\'ids\':DEVICES[\'A\']},{\'Authorization\':\'\'},401),\n  (\'wrong service token\',{\'ids\':DEVICES[\'A\']},{\'Authorization\':\'Bearer qa-invalid\'},401),\n  (\'wrong deployment\',{\'ids\':DEVICES[\'A\']},{\'X-Automation-Deployment\':\'qa-invalid\'},401),\n  (\'missing tenant\',{\'ids\':DEVICES[\'A\']},{\'X-Automation-Tenant\':\'\'},401),\n  (\'201 IDs rejected before dedupe\',{\'ids\':[DEVICES[\'A\'][0]]*201},{},400),\n  (\'empty IDs\',{\'ids\':[]},{},400),\n  (\'body tenant selector forbidden\',{\'ids\':DEVICES[\'A\'],\'tenant_id\':TENANTS[\'B\']},{},400)]:\n  record(name,lambda name=name,body=body,change=change,expected=expected:reject(name,body,change,expected))\n record(\'200 raw IDs allowed and deduped\',lambda:lookup(\'A\',[DEVICES[\'A\'][0]]*200,[DEVICES[\'A\'][0]]))\n def legacy(label):\n  seen=set();total=None\n  for page in [1,2]:\n   data,rows=response_rows(*transport(\'GET\',\'/internal/automation/devices?page=\'+str(page)+\'&page_size=2\',headers(TENANTS[label])),TENANTS[label])\n   ensure(len(rows)<=2 and data[\'total\']>=len(rows),\'legacy-pagination-shape\')\n   if total is not None:ensure(total==data[\'total\'],\'legacy-count-changed\')\n   total=data[\'total\'];ids={r[\'id\'] for r in rows};ensure(not seen.intersection(ids),\'legacy-page-overlap\');seen.update(ids)\n   if rows:\n    exact,looked=response_rows(*transport(\'POST\',\'/internal/automation/devices/lookup\',headers(TENANTS[label]),{\'ids\':list(ids)}),TENANTS[label])\n    ensure(exact[\'total\']==len(ids) and {r[\'id\']:r for r in rows}=={r[\'id\']:r for r in looked},\'legacy-lookup-parity\')\n  ensure(total>=2,\'legacy-fixtures-not-present\');return {\'tenant\':TENANTS[label],\'pages\':2,\'observed_count\':len(seen),\'total\':total,\'field_parity\':True}\n for label in [\'A\',\'B\']:record(label+\' old list pagination compatibility\',lambda label=label:legacy(label))\n return {\'status\':\'PASS\' if all(x[\'status\']==\'PASS\' for x in results) else \'FAIL\',\'checks\':results,\'read_only\':True,\'fixture_writes\':0,\'device_commands\':0,\'scope\':\'Service owner loopback boundary, not browser/user authorization; unknown UUID omitted does not assert global DB absence.\'}\n\ndef main():\n parser=argparse.ArgumentParser();parser.add_argument(\'--execute-loopback-readonly\',action=\'store_true\');args=parser.parse_args()\n ensure(args.execute_loopback_readonly,\'explicit-readonly-execution-required\')\n import fcntl\n lock=pathlib.Path(\'/opt/tp-community-actions/deployment.lock\');ensure(not lock.is_symlink(),\'lock-symlink\')\n with lock.open(\'r\') as f:\n  fcntl.flock(f,fcntl.LOCK_SH|fcntl.LOCK_NB)\n  token,deployment,pid=identity();transport=Transport();status,value=transport(\'GET\',\'/api/v1/sys_version\',{})\n  ensure(status==200 and value.get(\'data\',{}).get(\'version\')==\'gin-cas-command-\'+CANDIDATE,\'live-version-mismatch\')\n  result=probe(token,deployment,transport)\n  again_token,again_deployment,again_pid=identity()\n  ensure(again_pid==pid and hmac.compare_digest(token,again_token) and hmac.compare_digest(deployment,again_deployment),\'runtime-changed-during-probe\')\n  token=\'\';deployment=\'\';again_token=\'\';again_deployment=\'\'\n  result.update(receipt_schema=1,candidate=CANDIDATE,version=\'gin-cas-command-\'+CANDIDATE,binary_sha256=BINARY_SHA,process_contract_sha256=CONTRACT_SHA,pid=pid,pm_id=25,required_case_count=18)\n print(json.dumps(result))\n return 0 if result[\'status\']==\'PASS\' else 1\n\nif __name__==\'__main__\':\n try:raise SystemExit(main())\n except Exception as e:\n  print(json.dumps({\'status\':\'BLOCKED\',\'reason\':str(e) if isinstance(e,CheckFailed) else type(e).__name__,\'read_only\':True,\'fixture_writes\':0}))\n  raise SystemExit(1)\n'
import io,contextlib,sys,json,os,pathlib
ns={'__name__':'reviewed_readonly_probe'}
exec(compile(SOURCE,'reviewed-readonly-probe','exec'),ns)
sys.argv=['probe','--execute-loopback-readonly']
out=io.StringIO()
with contextlib.redirect_stdout(out): code=ns['main']()
result=json.loads(out.getvalue())
if code==0:
 path=ns['STAGE']/'directory-readonly-acceptance.json'
 fd=os.open(str(path),os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
 with os.fdopen(fd,'w') as f:json.dump(result,f);f.flush();os.fsync(f.fileno())
print(json.dumps(result))
raise SystemExit(code)
